      extras.buttons??=[];extras.cards??=[];extras.cardOrder??=[];extras.buttonOrder??=[];
      const title=standard?(section.headingFieldId?(plain(data.richFields?.[section.headingFieldId]?.[lang])||data.fields?.[section.headingFieldId]?.[lang]||section.title):section.title):(section.title?.[lang]||section.title?.en||'Untitled section');
